// en-GB, en-CA = en-US
t['en-GB'] = { ...t['en-US'] };
t['en-CA'] = { ...t['en-US'] };
// fr-CA = fr-FR
t['fr-CA'] = { ...t['fr-FR'] };

const langs = ['en-US','en-GB','en-CA','fr-FR','fr-CA','ca-ES','va-ES','eu-ES','gl-ES'];

langs.forEach(lang => {
  const fp = base + lang + '.json';
  const json = JSON.parse(fs.readFileSync(fp, 'utf8'));
  const translations = t[lang];
  for (const [dotPath, val] of Object.entries(translations)) {
    // Navigate and set
    const parts = dotPath.split('.');
    let cur = json;
    // prefix with 'info'
    const fullPath = 'info.' + dotPath;
    const fp2 = fullPath.split('.');
    const last = fp2.pop();
    let obj = json;
    for (const p of fp2) {
      const isNum = /^\d+$/.test(p);
      if (isNum) {
        const idx = parseInt(p);
        if (!Array.isArray(obj)) {
          // convert to array — unlikely but defensive
        }
        if (obj[idx] === undefined) obj[idx] = {};
        obj = obj[idx];
      } else {
        if (!obj[p]) obj[p] = {};
        obj = obj[p];
      }
    }
    obj[last] = val;
  }
  fs.writeFileSync(fp, JSON.stringify(json, null, 2), 'utf8');
  console.log(lang + ': info section updated');
});
